});
```

### Configure plugin

Configure `BlockquotePlugin` with the component and shortcut used by your app.
The `toggle` shortcut dispatches the plugin's structural toggle command.

```tsx
import { BlockquotePlugin } from 'platejs/react';
import { createEditor } from 'platejs/react';
import { BlockquoteElement } from '@/components/editor/blockquote';

const editor = createEditor({
  plugins: [
    // ...otherPlugins,
    BlockquotePlugin.configure({
      component: BlockquoteElement,
      shortcuts: { toggle: { keys: 'mod+shift+period' } },
    }),
  ],
});
```

- `.configure({ component })`: Assigns [`BlockquoteElement`](/docs/plate/components/blockquote) to render blockquote elements.
- `shortcuts.toggle`: Dispatches `editor.plugin(BlockquotePlugin).update.toggle()`.

### Turn into toolbar button

You can add blockquote to the [Turn Into Toolbar Button](/docs/plate/toolbar#turn-into-toolbar-button) to toggle blockquotes:

```tsx
import { PLUGINS } from 'platejs';

const turnIntoItem = {
  icon: <QuoteIcon />,
  label: 'Quote',
  value: PLUGINS.blockquote,
};
```

### Insert toolbar button

You can add blockquote to the [Insert Toolbar Button](/docs/plate/toolbar#insert-toolbar-button) to insert blockquotes:

```tsx
import { PLUGINS } from 'platejs';

const insertItem = {
  icon: <QuoteIcon />,
  label: 'Quote',
  value: PLUGINS.blockquote,
};
```

</Steps>

## Plugins

### `BlockquotePlugin`

Plugin for blockquote container elements. Renders as `<blockquote>` HTML element by default.

## Transforms

### `editor.plugin(BlockquotePlugin).update.wrap()`

Wrap each selected block in a blockquote, preserving unselected blocks and
leaving existing quotes intact. Pass `at` to target a location or node selection.

```tsx
editor.plugin(BlockquotePlugin).update.wrap();
```

### `editor.plugin(BlockquotePlugin).update.toggle()`

Wraps the current block or selection in a blockquote. If the selection is already inside a blockquote, it unwraps the quoted blocks.

```tsx
editor.plugin(BlockquotePlugin).update.toggle();
```

